def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        from datetime import datetime, timezone, timedelta, time as Time
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")

        # Convert nanoseconds to seconds and remainder nanoseconds
        seconds, remainder_nanoseconds = divmod(nanoseconds, 1_000_000_000)

        # Get the base time in UTC
        base_time = datetime.fromtimestamp(0, tz=timezone.utc) + timedelta(seconds=seconds, microseconds=remainder_nanoseconds // 1000)

        # Convert to the specified timezone if provided
        if tz is not None:
            if not hasattr(tz, "utcoffset"):
                raise ValueError("tz must be a timezone object with a utcoffset method")
            base_time = base_time.astimezone(tz)

        # Extract the time part
        return Time(base_time.hour, base_time.minute, base_time.second, base_time.microsecond)

    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import time, datetime, timezone, timedelta

    try:
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")

        seconds, remainder = divmod(nanoseconds, 1_000_000_000)
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)

        t = time(hour=hours, minute=minutes, second=seconds, microsecond=remainder // 1_000)

        if tz is not None:
            if not isinstance(tz, (str, timezone)):
                raise ValueError("tz must be a timezone string or a datetime.timezone object")
            if isinstance(tz, str):
                tz = timezone(timedelta(hours=int(tz)))
            t = datetime.combine(datetime.min, t).replace(tzinfo=tz).timetz()

        return t

    except Exception as e:
        raise ValueError(f"Error hydrating time: {str(e)}")

