def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            try:
                if timeout is not None and timeout < 0:
                    raise ValueError("Timeout value should not be negative.")
                if metadata is not None and not isinstance(metadata, dict):
                    raise TypeError("Metadata should be a dictionary.")
                tx_options = {}
                if metadata:
                    tx_options['metadata'] = metadata
                if timeout is not None:
                    tx_options['timeout'] = timeout
                return func(tx, *args, **kwargs)
            except Exception as e:
                raise e
        return wrapper
    return decorator

