def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    try:
        if not cmd:
            raise ValueError("Command tuple cannot be empty.")

        # Convert the command to a list for mutability
        cmd_list = list(cmd)

        # Check if the first element is a script with a shebang
        if cmd_list[0].endswith('.py'):
            # Prepend 'python' to the command to ensure correct shebang handling on Windows
            cmd_list.insert(0, 'python')

        # Return the normalized command as a tuple
        return tuple(cmd_list)

    except Exception as e:
        # Handle any exceptions and re-raise with a descriptive message
        raise ValueError(f"Failed to normalize command: {e}")

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
