def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    try:
        if not cmd:
            raise ValueError("Command tuple is empty")

        # Convert the command to a list for mutability
        cmd_list = list(cmd)

        # Check if the first element contains a shebang
        if cmd_list[0].startswith('#!'):
            # Remove the shebang line
            cmd_list[0] = cmd_list[0].split('\n', 1)[1]
            # Prepend the path to the Python interpreter
            import sys
            cmd_list.insert(0, sys.executable)

        # Handle deep-path issues by shortening the path if possible
        import os
        if os.name == 'nt':  # Check if the OS is Windows
            try:
                from shutil import which
                first_cmd = which(cmd_list[0])
                if first_cmd:
                    cmd_list[0] = first_cmd
            except Exception as e:
                print(f"Failed to resolve command path: {e}")

        # Convert back to tuple before returning
        return tuple(cmd_list)
    except Exception as e:
        print(f"An error occurred: {e}")
        return cmd

