def extostr(cls, e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise TypeError("e must be an instance of Exception")
    if not isinstance(max_level, int) or max_level < 0:
        raise ValueError("max_level must be a non-negative integer")
    if not isinstance(max_path_level, int) or max_path_level < 0:
        raise ValueError("max_path_level must be a non-negative integer")

    try:
        exc_type = type(e).__name__
        exc_msg = str(e)
        trace = []
        import traceback
        for frame_info in traceback.extract_tb(e.__traceback__, limit=max_level):
            filename = '/'.join(frame_info.filename.split('/')[-max_path_level:])
            trace.append(f"  File \"{filename}\", line {frame_info.lineno}, in {frame_info.name}\n    {frame_info.line}")
        trace_str = '\n'.join(trace)
        return f"{exc_type}: {exc_msg}\n{trace_str}"
    except Exception as ex:
        return f"Failed to format exception: {str(ex)}"

