def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track unique classes and a list to maintain order
        seen = set()
        minimized = []

        # Iterate over the classes in reverse to maintain the method resolution order
        for cls in reversed(classes):
            # If the class is not already seen, add it to the minimized list and mark as seen
            if cls not in seen:
                seen.add(cls)
                minimized.append(cls)

        # Return the list in the correct order
        return list(reversed(minimized))
    except Exception as e:
        # Handle any unexpected exceptions
        print(f"An error occurred: {e}")
        return []

