            out_params = {k: params[k] for k in params}
            for key in params:
                placeholder = f"%({key})s"
                new_sql = new_sql.replace(f":{key}", placeholder)
        elif self.in_style in ('qmark', 'numeric', 'format', 'pyformat'):
            if not isinstance(params, Sequence):
                raise ValueError("Params must be a sequence for ordinal parameters.")
            new_sql = sql
            out_params = list(params)
            if self.in_style == 'qmark':
