def _explore_folder(folder):
    import os
    from collections import defaultdict

    if not isinstance(folder, str):
        raise ValueError("Folder must be a string.")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The folder {folder} does not exist or is not a directory.")

    packages_data = defaultdict(list)

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                base_name = os.path.splitext(filename)[0]
                file_path = os.path.join(folder, filename)
                with open(file_path, 'r', encoding='utf-8') as file:
                    content = file.read()
                    packages_data[base_name].append(content)
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the folder: {e}")

    return dict(packages_data)

def _explore_folder(folder):
    import os
    import xml.etree.ElementTree as ET
    from collections import defaultdict

    package_data = defaultdict(list)
    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                file_path = os.path.join(folder, filename)
                tree = ET.parse(file_path)
                root = tree.getroot()
                base_name = os.path.splitext(filename)[0]
                package_data[base_name].append(ET.tostring(root, encoding='unicode'))
    except FileNotFoundError:
        print(f"The folder {folder} does not exist.")
    except ET.ParseError:
        print(f"Error parsing one or more XML files in the folder {folder}.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    return dict(package_data)

def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise ValueError("The folder parameter must be a string.")

    if not os.path.isdir(folder):
        raise ValueError(f"The folder {folder} does not exist or is not a directory.")

    package_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    basename = os.path.splitext(os.path.basename(file))[0]
                    package_data[basename].append({
                        'path': file_path,
                        'root_element': root_element.tag,
