def _explore_zipfile(zip_path):
    import zipfile
    import os
    from xml.etree import ElementTree as ET

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            file_list = zip_ref.namelist()
    except (zipfile.BadZipFile, FileNotFoundError) as e:
        print(f"Error opening zip file: {e}")
        return {}

    package_data = {}
    for file in file_list:
        if file.endswith('.xml'):
            base_name = os.path.splitext(os.path.basename(file))[0]
            try:
                with zip_ref.open(file) as xml_file:
                    tree = ET.parse(xml_file)
                    root = tree.getroot()
                    # Here you can customize how you want to extract data from the XML
                    # For demonstration, let's just store the entire XML string
                    xml_data = ET.tostring(root, encoding='unicode')
                    if base_name in package_data:
                        package_data[base_name].append(xml_data)
                    else:
                        package_data[base_name] = [xml_data]
            except ET.ParseError as e:
                print(f"Error parsing XML file {file}: {e}")
            except Exception as e:
                print(f"Error reading file {file}: {e}")

    return package_data

