            number = issue_content[:number_end]
            suppl = issue_content[number_end:].strip().lstrip('-')

        # Clean up suppl
        if suppl:
            suppl = suppl.replace('suppl', 'suppl ').replace('spe', 'spe ').replace('supp', 'suppl ').replace('s', 'suppl ').replace('.', ' ').replace('-', ' ').strip()
