def pretty(self, indent=0, debug=False):
    try:
        indent_str = ' ' * indent
        output = f"{indent_str}<{self.__class__.__name__}>\n"
        for key, value in self.__dict__.items():
            if isinstance(value, object) and not isinstance(value, (str, int, float, bool, list, tuple, dict, set)):
                if debug:
                    output += f"{indent_str}  {key}: <object>\n"
                else:
                    output += f"{indent_str}  {key}: {value.pretty(indent + 2, debug)}\n"
            else:
                output += f"{indent_str}  {key}: {value}\n"
        return output
    except Exception as e:
        return f"{indent_str}<ERROR: {str(e)}>"

