def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    result = []
    for expr in args:
        if not isinstance(expr, tuple) or len(expr) != 3:
            result.append(expr)
            continue

        op, left, right = expr
        if op == '&':
            if right == ('|', left, ('~', left, '_')):
                result.append(('&', left, right[2]))
            elif right == ('|', left, ('~', left, right[2])):
                result.append(left)
            elif left == ('|', right, ('~', right, '_')):
                result.append(('&', left, left[2]))
            elif left == ('|', right, ('~', right, left[2])):
                result.append(right)
            else:
                result.append(expr)
        elif op == '|':
            if right == ('&', left, ('~', left, '_')):
                result.append(('|', left, right[2]))
            elif right == ('&', left, ('~', left, right[2])):
                result.append(left)
            elif left == ('&', right, ('~', right, '_')):
                result.append(('|', left, left[2]))
            elif left == ('&', right, ('~', right, left[2])):
                result.append(right)
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

