def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import argparse
        import borgmatic.commands.arguments

        parser = borgmatic.commands.arguments.make_parsers()
        script = ""

        def add_arguments(completion_script, command, subparsers):
            for subcommand, subparser in subparsers.choices.items():
                completion_script += f"    {command} {subcommand} "
                for action in subparser._actions:
                    if isinstance(action, argparse._SubParsersAction):
                        add_arguments(completion_script, f"{command} {subcommand}", action.choices)
                    else:
                        for option in action.option_strings:
                            completion_script += f"{option} "
                completion_script += "\n"

        script += "_borgmatic_completion() {\n"
        script += "    local cur prev opts\n"
        script += "    COMPREPLY=()\n"
        script += "    cur=\"${COMP_WORDS[COMP_CWORD]}\"\n"
        script += "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n"
        script += "    opts=\""

        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                add_arguments(script, "", action.choices)
            else:
                for option in action.option_strings:
                    script += f"{option} "

        script += "\"\n\n"
        script += "    case \"${prev}\" in\n"
        script += "        *)\n"
        script += "            COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )\n"
        script += "            ;;\n"
        script += "    esac\n"
        script += "}\n"
        script += "complete -F _borgmatic_completion borgmatic\n"

        return script

    except Exception as e:
        return f"# Error generating bash completion script: {str(e)}"

