def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    try:
        number = float(size[:-1])
    except ValueError:
        try:
            number = float(size)
            return int(number)
        except ValueError:
            raise ValueError("Invalid number in size string")

    unit = size[-1].upper()
    if unit == 'K':
        return int(number * 1000)
    elif unit == 'M':
        return int(number * 1000**2)
    elif unit == 'G':
        return int(number * 1000**3)
    elif unit == 'T':
        return int(number * 1000**4)
    else:
        raise ValueError("Unknown unit in size string: " + unit)

