def get_repo_archive(url: str, destination_path: Path) -> Path:
    import requests
    import tarfile
    import os

    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()

        with tarfile.open(fileobj=response.raw, mode='r:gz') as tar:
            tar.extractall(path=destination_path)

        # Assuming the tar file extracts into a single directory, return that path
        extracted_contents = os.listdir(destination_path)
        if len(extracted_contents) == 1 and os.path.isdir(destination_path / extracted_contents[0]):
            return destination_path / extracted_contents[0]
        else:
            return destination_path

    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to download the file: {e}")
    except tarfile.TarError as e:
        raise Exception(f"Failed to extract the tar file: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

