def addignored(ignored):
    try:
        # Run the git command to get ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Process the output to get file names
        ignored_files = set()
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) > 2:
                file_path = parts[2]
                ignored_files.add(file_path)

        # Sort the list of ignored files
        sorted_files = sorted(ignored_files)

        # Join the sorted list into a single string separated by commas
        return ','.join(sorted_files)

    except subprocess.CalledProcessError as e:
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"

