def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os
    import importlib

    if not callable(func):
        raise ValueError("The provided func must be callable.")

    module_name = func.__module__
    function_name = func.__name__

    if module_name == '__main__':
        raise ValueError("The function must be in a module that is importable.")

    full_command = [
        'python', '-c',
        f'import {module_name}; {module_name}.{function_name}({", ".join(repr(arg) for arg in args)})'
    ]

    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    try:
        result = subprocess.run(
            full_command,
            env=env,
            check=True,
            timeout=timeout,
            capture_output=True,
            text=True
        )
        return result.stdout
    except subprocess.TimeoutExpired as e:
        raise TimeoutError(f"The subprocess command '{' '.join(full_command)}' timed out after {timeout} seconds.") from e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"The subprocess command '{' '.join(full_command)}' returned non-zero exit status {e.returncode}. Output: {e.output}, Error: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the subprocess command '{' '.join(full_command)}': {str(e)}") from e

