def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        # Ensure commands and args are lists
        if not isinstance(commands, list) or not isinstance(args, list):
            raise ValueError("Both commands and args must be lists.")

        # Combine commands and args
        full_command = commands + args

        # Set up the subprocess arguments
        subprocess_args = {
            'args': full_command,
            'cwd': cwd,
            'env': env
        }

        # Redirect stderr if hide_stderr is True
        if hide_stderr:
            subprocess_args['stderr'] = subprocess.DEVNULL

        # Run the command
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        result = subprocess.run(**subprocess_args, capture_output=True, text=True, check=True)

        return result.stdout

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}: {e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

