def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    try:
        all_nodes = set(graph.all_nodes())
        children = {o for s, p, o in graph.triples((None, prop, None))}
        parents = {s for s, p, o in graph.triples((None, prop, None))}

        roots = all_nodes - children
    except Exception as e:
        print(f"An error occurred: {e}")

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    try:
        # Find all nodes that are parents
        parents = {obj for subj, pred, obj in graph.triples((None, prop, None))}

        # Find all nodes that are children
        children = {subj for subj, pred, obj in graph.triples((None, prop, None))}

        # Roots are those that are parents but not children
        roots.update(parents - children)

        return roots
    except Exception as e:
        raise ValueError(f"An error occurred while finding roots: {e}")

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        for s, p, o in graph:
            if p == prop:
                roots.add(o)
                children = set(graph.subjects(predicate=prop, object=o))
                for child in children:
                    if child in roots:
                        roots.remove(child)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

