def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import logging

    config_dict = {}
    error_records = []

    if not isinstance(config_filenames, (list, tuple)):
        error_msg = f"Invalid config_filenames type: {type(config_filenames)}. Expected list or tuple."
        error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))
        return config_dict, error_records

    if overrides is not None and not isinstance(overrides, dict):
        error_msg = f"Invalid overrides type: {type(overrides)}. Expected dict or None."
        error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))
        return config_dict, error_records

    for filename in config_filenames:
        if not isinstance(filename, str):
            error_msg = f"Invalid filename type: {type(filename)}. Expected str."
            error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                if overrides:
                    config.update(overrides)
                config_dict[filename] = config
        except FileNotFoundError:
            error_msg = f"Configuration file not found: {filename}"
            error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))
        except json.JSONDecodeError as e:
            error_msg = f"Error decoding JSON from file {filename}: {e}"
            error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))
        except Exception as e:
            error_msg = f"Unexpected error processing {filename}: {e}"
            error_records.append(logging.makeLogRecord({'levelno': logging.ERROR, 'msg': error_msg}))

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json
    from configparser import ConfigParser

    configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            if filename.endswith('.json'):
                with open(filename, 'r') as f:
                    config = json.load(f)
            elif filename.endswith('.ini'):
                config_parser = ConfigParser()
                config_parser.read(filename)
                config = {section: dict(config_parser.items(section)) for section in config_parser.sections()}
            else:
                raise ValueError(f"Unsupported configuration file type for {filename}")

            if overrides and filename in overrides:
                config.update(overrides[filename])

            if resolve_env:
                config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

            configs[filename] = config

        except Exception as e:
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(log_record)

    return configs, log_records

