def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import configparser

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            config = configparser.ConfigParser()
            config.read(filename)

            if resolve_env:
                for section in config.sections():
                    for key, value in config.items(section):
                        config.set(section, key, os.path.expandvars(value))

            config_dict[filename] = dict(config)

            # Apply overrides
            for section, settings in overrides.get(filename, {}).items():
                if section not in config_dict[filename]:
                    config_dict[filename][section] = {}
                config_dict[filename][section].update(settings)

        except Exception as e:
            log_record = logging.makeLogRecord({
                'levelname': 'ERROR',
                'message': f"Error parsing configuration file {filename}: {e}"
            })
            log_records.append(log_record)

    return config_dict, log_records

