def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    modified_text = []
    tag = ""
    i = 0
    while i < len(text):
        char = text[i]
        if char == '`':
            in_code_block = not in_code_block
            modified_text.append(char)
        elif char == '#' and not in_code_block:
            tag = ""
            while i + 1 < len(text) and text[i + 1].isalnum():
                tag += text[i + 1]
                i += 1
            if tag:
                tags.add(tag)
                if replacer:
                    modified_text.append(replacer(tag))
                else:
                    modified_text.append(f"#{tag}")
        else:
            modified_text.append(char)
        i += 1
    return tags, ''.join(modified_text)

